function getFeatureCentroid(feature){const geometry=feature.geometry;if(!geometry)return null;let allCoords=[];if(geometry.type==='Polygon'){allCoords=geometry.coordinates[0];}else if(geometry.type==='MultiPolygon'){geometry.coordinates.forEach(polygon=>{allCoords=allCoords.concat(polygon[0]);});}else{return null;}
let sumLat=0,sumLng=0;allCoords.forEach(coord=>{sumLng+=coord[0];sumLat+=coord[1];});return[sumLat/allCoords.length,sumLng/allCoords.length];}
