console.log(`Cell dimensions: latStep=${latStep.toFixed(4)}, lngStep=${lngStep.toFixed(4)}`);console.log(`First lat: ${lats[0]}, Last lat: ${lats[lats.length-1]}`);console.log(`First lng: ${lngs[0]}, Last lng: ${lngs[lngs.length-1]}`);const rectangles=[];for(let i=0;i<lats.length;i++){for(let j=0;j<lngs.length;j++){const value=values[i][j];if(value!==null&&value!==undefined){const[r,g,b,a]=getColorForValue(value,gradient);const cellNorth=lats[i]+latStep/2;const cellSouth=lats[i]-latStep/2;const cellWest=lngs[j]-lngStep/2;const cellEast=lngs[j]+lngStep/2;const cellBounds=[[cellSouth,cellWest],[cellNorth,cellEast]];const rect=L.rectangle(cellBounds,{color:'transparent',weight:0,fillColor:`rgb(${r}, ${g}, ${b})`,fillOpacity:a,interactive:false});rectangles.push(rect);}}}
