document.addEventListener('DOMContentLoaded',function(){const hamburgerMenu=document.getElementById('hamburgerMenu');const dropdownMenu=document.getElementById('dropdownMenu');if(hamburgerMenu&&dropdownMenu){hamburgerMenu.addEventListener('click',function(e){e.stopPropagation();hamburgerMenu.classList.toggle('active');dropdownMenu.classList.toggle('active');});document.addEventListener('click',function(e){if(!hamburgerMenu.contains(e.target)&&!dropdownMenu.contains(e.target)){hamburgerMenu.classList.remove('active');dropdownMenu.classList.remove('active');}});const dropdownLinks=dropdownMenu.querySelectorAll('.dropdown-link');dropdownLinks.forEach(link=>{link.addEventListener('click',function(){hamburgerMenu.classList.remove('active');dropdownMenu.classList.remove('active');});});}});if(window.innerWidth<=768){const weatherPanel=document.getElementById('weatherDetailsPanelSection');let startY=0;let currentY=0;let isDragging=false;if(weatherPanel){weatherPanel.addEventListener('scroll',function(){if(weatherPanel.scrollTop>50&&!weatherPanel.classList.contains('expanded')){weatherPanel.classList.add('expanded');}});weatherPanel.addEventListener('touchstart',function(e){if(weatherPanel.scrollTop===0){startY=e.touches[0].clientY;isDragging=true;}});weatherPanel.addEventListener('touchmove',function(e){if(isDragging&&weatherPanel.scrollTop===0){currentY=e.touches[0].clientY;const diff=currentY-startY;if(diff>0){e.preventDefault();}}});weatherPanel.addEventListener('touchend',function(e){if(isDragging){const diff=currentY-startY;if(diff>50&&weatherPanel.classList.contains('expanded')){weatherPanel.classList.remove('expanded');weatherPanel.scrollTop=0;}
isDragging=false;}});}}